/**
 * Sub-issue tree invariants: no cycles, a shallow bounded depth, and the
 * descendant/rollup math that `setIssueParent`, `listSubIssues`,
 * `getIssueRollup` and the archive cascade all share.
 */
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IsoTimestamp, IssueId } from "@/types/common";
import type { IssueRollup, IssueStatus } from "@/types/issue";

/** Minimal shape needed to reason about a project's issue tree. */
export interface IssueTreeNode {
  readonly id: IssueId;
  readonly parentId: IssueId | null;
  readonly status: IssueStatus;
  readonly archivedAt: IsoTimestamp | null;
}

/** Raised when placing or moving an issue would create a cycle or exceed `MAX_SUB_ISSUE_DEPTH`. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its own sub-issues.`
        : `Issue ${issueId} cannot be moved there: a sub-issue would sit too deep.`,
    );
    this.name = "IssueHierarchyError";
  }
}

function childrenIndex(
  nodes: readonly IssueTreeNode[],
): ReadonlyMap<IssueId, readonly IssueTreeNode[]> {
  const index = new Map<IssueId, IssueTreeNode[]>();
  for (const node of nodes) {
    if (node.parentId === null) continue;
    const siblings = index.get(node.parentId);
    if (siblings) {
      siblings.push(node);
    } else {
      index.set(node.parentId, [node]);
    }
  }
  return index;
}

/**
 * Every issue below `rootId`, at any depth; `rootId` itself is excluded.
 * Returned in level order, so a node's ancestors always precede it.
 */
export function descendantsOf(
  nodes: readonly IssueTreeNode[],
  rootId: IssueId,
): readonly IssueTreeNode[] {
  const children = childrenIndex(nodes);
  const result: IssueTreeNode[] = [];
  const queue = [...(children.get(rootId) ?? [])];

  while (queue.length > 0) {
    const node = queue.shift() as IssueTreeNode;
    result.push(node);
    queue.push(...(children.get(node.id) ?? []));
  }

  return result;
}

/** 0 for a leaf; otherwise the depth of its deepest descendant, relative to `rootId`. */
export function subtreeHeight(
  nodes: readonly IssueTreeNode[],
  rootId: IssueId,
): number {
  const children = childrenIndex(nodes);

  function heightFrom(id: IssueId): number {
    const kids = children.get(id) ?? [];
    if (kids.length === 0) return 0;
    return 1 + Math.max(...kids.map((kid) => heightFrom(kid.id)));
  }

  return heightFrom(rootId);
}

/** 0 for a root issue; otherwise one more than its parent's level. */
export function levelOf(
  nodes: readonly IssueTreeNode[],
  issueId: IssueId,
): number {
  const byId = new Map(nodes.map((node) => [node.id, node] as const));
  let level = 0;
  let current = byId.get(issueId);
  while (current && current.parentId !== null) {
    level += 1;
    current = byId.get(current.parentId);
  }
  return level;
}

/** True when placing `issueId` under `parentId` would create a cycle. */
export function wouldCycle(
  nodes: readonly IssueTreeNode[],
  issueId: IssueId,
  parentId: IssueId,
): boolean {
  if (parentId === issueId) return true;
  return descendantsOf(nodes, issueId).some((node) => node.id === parentId);
}

/** Counts over every live descendant of `rootId`, at any depth. */
export function rollupOf(
  nodes: readonly IssueTreeNode[],
  rootId: IssueId,
): IssueRollup {
  const live = descendantsOf(nodes, rootId).filter(
    (node) => node.archivedAt === null,
  );
  const closed = live.filter((node) =>
    CLOSED_ISSUE_STATUSES.includes(node.status),
  ).length;

  return { total: live.length, open: live.length - closed, closed };
}

