/**
 * Archiving cascades to every live issue below it, at any depth. Each one —
 * the target and every descendant — gets its own `issue.archived` event, the
 * target first so a descendant's direct parent is always archived by the
 * time its own event fires.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  const descendantIds = await issueRepo.listLiveDescendantIds(
    orgId,
    archived.projectId,
    archived.id,
  );

  for (const descendantId of descendantIds) {
    const archivedDescendant = await issueRepo.archiveIssue(orgId, descendantId);
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archivedDescendant.id,
      projectId: archivedDescendant.projectId,
    });
  }

  return archived;
}

