/**
 * Places, moves or roots an issue. Judged against the issue's whole subtree —
 * sub-issues move with their parent, so a move is refused if its *deepest*
 * descendant would land past `MAX_SUB_ISSUE_DEPTH`.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId === issue.parentId) return issue;

  if (input.parentId !== null) {
    const parent = requireFound(
      await issueRepo.findIssueById(input.orgId, input.parentId),
      "Issue",
      input.parentId,
    );
    if (parent.projectId !== issue.projectId) {
      throw new NotFoundError("Issue", input.parentId);
    }
    assertNotArchived("Issue", parent.id, parent);

    const tree = await issueRepo.listIssueTree(input.orgId, issue.projectId);

    if (wouldCycle(tree, issue.id, parent.id)) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }

    const newLevel = levelOf(tree, parent.id) + 1;
    const height = subtreeHeight(tree, issue.id);
    if (newLevel + height > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

