/**
 * Tells an issue's assignee once its sub-issue tree has no open issue left.
 * Only the direct parent is considered, and a parent that is itself archived,
 * unassigned or has no sub-issues at all is left alone.
 */
async function notifySubIssuesCompleted(
  orgId: OrgId,
  issue: Issue,
  actorId: UserId | null,
): Promise<void> {
  if (issue.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, issue.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const rollup = await issueRepo.getIssueRollup(orgId, parent.projectId, parent.id);
  if (rollup.total === 0 || rollup.open > 0) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are closed",
    body: `Every sub-issue below issue ${parent.id} is now closed`,
    href: `/issues/${parent.id}`,
    actorId,
  });
}

