    await issueService.changeIssueStatus(tenant.actors.member, { orgId: tenant.org.id, issueId: childA.id, status: "done" });

    let notifs = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, kind: ["sub_issues_completed"], limit: 25, cursor: null,
    });
    expect(notifs.items).toHaveLength(0); // childB still open

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, childB.id);

    notifs = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, kind: ["sub_issues_completed"], limit: 25, cursor: null,
    });
    expect(notifs.items).toHaveLength(1);

    const rollup = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, parent.id);
    expect(rollup).toEqual({ total: 3, open: 0, closed: 1 });

    // Now archive the whole parent subtree; cascade should not spam more notifications.
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);

    notifs = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, kind: ["sub_issues_completed"], limit: 25, cursor: null,
    });
    expect(notifs.items).toHaveLength(1); // unchanged — no new notification from the cascade
  });
});

